  "zhCN": "点「＋」添加图片模板，可一次选多张；添加后立刻存进模板库，下次打开或新建手帐本都能继续用。",
  "zhTW": "點「＋」新增圖片範本，可一次選多張；新增後立刻存進範本庫，下次開啟或新建手帳本都能繼續用。",
  "en": "Tap \"+\" to add image templates. You can select several at once; they are saved to the template library immediately, so you can keep using them next time you open or create a journal.",
  "ja": "「＋」をタップして画像テンプレートを追加します。複数まとめて選択できます。追加するとすぐにテンプレートライブラリに保存され、次回開いたときや新しい手帳を作成するときも使えます。",
  "fr": "Appuyez sur « + » pour ajouter des modèles d'image. Vous pouvez en sélectionner plusieurs à la fois ; ils sont enregistrés immédiatement dans la bibliothèque de modèles et restent disponibles la prochaine fois que vous ouvrez ou créez un carnet.",
  "es": "Toca \"+\" para añadir plantillas de imagen. Puedes seleccionar varias a la vez; se guardan en la biblioteca de plantillas al instante, para que puedas seguir usándolas la próxima vez que abras o crees un diario."
