 "加密后本机与导出的源文件里都只存密文；正文文字、图片、照片封面、模板图都由密钥保护。密钥不会写进导出文件，也没有找回通道。": {
  "zhCN": "加密后本机与导出的源文件里都只存密文；正文文字、图片、照片封面、模板图都由密钥保护。密钥不会写进导出文件，也没有找回通道。",
  "zhTW": "加密後本機與匯出的原始檔裡都只存密文；內文文字、圖片、照片封面、範本圖都由密鑰保護。密鑰不會寫進匯出檔案，也沒有找回管道。",
  "en": "After encryption, only ciphertext is stored locally and in exported source files; body text, images, photo covers, and template images are all protected by the passkey. The passkey is never written into exported files, and there is no way to recover it.",
  "ja": "暗号化後は、端末内と書き出した元ファイルの両方に暗号文のみが保存されます。本文の文字、画像、写真の表紙、テンプレート画像はすべてパスキーで保護されます。パスキーは書き出しファイルには保存されず、復旧手段もありません。",
  "fr": "Après chiffrement, seul le texte chiffré est stocké localement et dans les fichiers sources exportés ; le texte du corps, les images, les couvertures photo et les images de modèles sont tous protégés par la clé d'accès. La clé n'est jamais incluse dans les fichiers exportés et il n'existe aucun moyen de la récupérer.",
  "es": "Tras el cifrado, solo se guarda texto cifrado tanto en el dispositivo como en los archivos de origen exportados; el texto del cuerpo, las imágenes, las portadas con fotos y las imágenes de plantillas están protegidos por la clave de acceso. La clave nunca se escribe en los archivos exportados y no hay forma de recuperarla."
 },
