 "<div class=\"lk-qsmall\">保密问题：{0}</div>": {
  "zhCN": "<div class=\"lk-qsmall\">保密问题：{0}</div>",
  "zhTW": "<div class=\"lk-qsmall\">保密問題：{0}</div>",
  "en": "<div class=\"lk-qsmall\">Security question: {0}</div>",
  "ja": "<div class=\"lk-qsmall\">秘密の質問：{0}</div>",
  "fr": "<div class=\"lk-qsmall\">Question de sécurité : {0}</div>",
  "es": "<div class=\"lk-qsmall\">Pregunta de seguridad: {0}</div>"
 },
 "<p class=\"lk-note lk-warn\">加密后：本机与导出的 .json 里只存密文；正文文字、图片、照片封面、模板图全部由密钥保护。密钥不会写进导出文件，也没有找回通道。解锁后可导出 PDF / SVG，但那两种是未加密的明文副本，请自行保管。</p>": {
  "zhCN": "<p class=\"lk-note lk-warn\">加密后：本机与导出的 .json 里只存密文；正文文字、图片、照片封面、模板图全部由密钥保护。密钥不会写进导出文件，也没有找回通道。解锁后可导出 PDF / SVG，但那两种是未加密的明文副本，请自行保管。</p>",
  "zhTW": "<p class=\"lk-note lk-warn\">加密後：本機與匯出的 .json 裡只存密文；正文文字、圖片、照片封面、範本圖全部由密鑰保護。密鑰不會寫進匯出檔案，也沒有找回管道。解鎖後可匯出 PDF / SVG，但那兩種是未加密的明文副本，請自行保管。</p>",
  "en": "<p class=\"lk-note lk-warn\">After encryption: only ciphertext is stored locally and in exported .json files; body text, images, photo covers and template images are all protected by the passkey. The passkey is never written into exported files, and there is no recovery channel. Once unlocked you can export PDF / SVG, but those two are unencrypted plaintext copies — keep them safe yourself.</p>",
  "ja": "<p class=\"lk-note lk-warn\">暗号化後：ローカルと書き出した .json には暗号文のみ保存されます。本文の文字、画像、写真の表紙、テンプレート画像はすべてパスキーで保護されます。パスキーは書き出しファイルには記録されず、復旧の手段もありません。ロック解除後は PDF / SVG に書き出せますが、これらは暗号化されていない平文のコピーなので、各自で管理してください。</p>",
  "fr": "<p class=\"lk-note lk-warn\">Après chiffrement : seul le texte chiffré est stocké localement et dans les fichiers .json exportés ; le texte du corps, les images, les couvertures photo et les images de modèles sont tous protégés par la clé d'accès. La clé n'est jamais écrite dans les fichiers exportés et il n'existe aucun moyen de la récupérer. Après déverrouillage, vous pouvez exporter en PDF / SVG, mais ces deux formats sont des copies en clair non chiffrées : conservez-les vous-même en toute sécurité.</p>",
  "es": "<p class=\"lk-note lk-warn\">Tras el cifrado: solo se guarda texto cifrado en el dispositivo y en los archivos .json exportados; el texto del cuerpo, las imágenes, las portadas con foto y las imágenes de plantillas están protegidos por la clave de acceso. La clave nunca se escribe en los archivos exportados y no hay forma de recuperarla. Tras desbloquear puedes exportar a PDF / SVG, pero esos dos formatos son copias sin cifrar en texto plano: guárdalas tú mismo.</p>"
 },
