 "<div class=\"diy-hint\">先点纸上的文字框，或按底栏「＋文字」新建一条</div>": {
  "zhCN": "<div class=\"diy-hint\">先点纸上的文字框，或按底栏「＋文字」新建一条</div>",
  "zhTW": "<div class=\"diy-hint\">先點紙上的文字框，或按底欄「＋文字」新增一條</div>",
  "en": "<div class=\"diy-hint\">First tap a text box on the paper, or press \"＋Text\" in the bottom bar to create one</div>",
  "ja": "<div class=\"diy-hint\">まず紙面上のテキストボックスをタップするか、下部バーの「＋テキスト」で新規作成してください</div>",
  "fr": "<div class=\"diy-hint\">Touchez d'abord une zone de texte sur le papier, ou appuyez sur « + Texte » dans la barre inférieure pour en créer une</div>",
  "es": "<div class=\"diy-hint\">Primero toca un cuadro de texto en el papel, o pulsa \"＋Texto\" en la barra inferior para crear uno</div>"
 },
 "<div class=\"diy-hint\">只调右侧翻口两个角，左侧书脊两角固定；画布与成品封面同度，点「完成」后保存。</div>": {
  "zhCN": "<div class=\"diy-hint\">只调右侧翻口两个角，左侧书脊两角固定；画布与成品封面同度，点「完成」后保存。</div>",
  "zhTW": "<div class=\"diy-hint\">只調右側翻口兩個角，左側書脊兩角固定；畫布與成品封面同度，點「完成」後儲存。</div>",
  "en": "<div class=\"diy-hint\">Only adjust the two corners on the right fore-edge; the two corners on the left spine stay fixed. The canvas is the same size as the finished cover; tap \"Done\" to save.</div>",
  "ja": "<div class=\"diy-hint\">右側の小口側の2つの角のみ調整できます。左側の背表紙の2角は固定です。キャンバスは完成した表紙と同じサイズです。「完了」をタップして保存してください。</div>",
  "fr": "<div class=\"diy-hint\">N'ajustez que les deux coins du bord droit ; les deux coins du dos à gauche restent fixes. La toile a la même taille que la couverture finale ; appuyez sur « Terminé » pour enregistrer.</div>",
  "es": "<div class=\"diy-hint\">Ajusta solo las dos esquinas del borde derecho; las dos esquinas del lomo izquierdo permanecen fijas. El lienzo tiene el mismo tamaño que la portada final; pulsa \"Listo\" para guardar.</div>"
 },
 "<div class=\"diy-hint\">当前装帧没有彩带：方形画册 / 精装书显示书槽，活页封面保持干净。</div>": {
  "zhCN": "<div class=\"diy-hint\">当前装帧没有彩带：方形画册 / 精装书显示书槽，活页封面保持干净。</div>",
  "zhTW": "<div class=\"diy-hint\">當前裝幀沒有彩帶：方形畫冊 / 精裝書顯示書槽，活頁封面保持乾淨。</div>",
  "en": "<div class=\"diy-hint\">This binding has no ribbon: square albums and hardcovers show a spine groove, while loose-leaf covers stay clean.</div>",
  "ja": "<div class=\"diy-hint\">この製本にはリボンがありません。スクエアルバム / ハードカバーでは背の溝が表示され、ルーズリーフの表紙はすっきりしたままです。</div>",
  "fr": "<div class=\"diy-hint\">Cette reliure n'a pas de ruban : les albums carrés et les reliés montrent une rainure au dos, tandis que les couvertures à feuillets mobiles restent nettes.</div>",
  "es": "<div class=\"diy-hint\">Este encuadernado no tiene cinta: los álbumes cuadrados y los libros de tapa dura muestran la ranura del lomo, mientras que las portadas de hojas sueltas se mantienen limpias.</div>"
 },
 "<div class=\"diy-hint\">英文字体只作用于拉丁字母，汉字仍走上面的中文字体；双击纸面文字可直接输入，关掉面板后长按 420ms 解锁才能拖四角改框 / 拖右侧手柄旋转</div>": {
  "zhCN": "<div class=\"diy-hint\">英文字体只作用于拉丁字母，汉字仍走上面的中文字体；双击纸面文字可直接输入，关掉面板后长按 420ms 解锁才能拖四角改框 / 拖右侧手柄旋转</div>",
  "zhTW": "<div class=\"diy-hint\">英文字體只作用於拉丁字母，漢字仍走上面的中文字體；雙擊紙面文字可直接輸入，關掉面板後長按 420ms 解鎖才能拖四角改框 / 拖右側手柄旋轉</div>",
  "en": "<div class=\"diy-hint\">The English font only applies to Latin letters; Chinese characters still use the Chinese font above. Double-click text on the paper to type directly. After closing the panel, long-press for 420 ms to unlock before you can drag the four corners to resize the box or drag the right handle to rotate.</div>",
  "ja": "<div class=\"diy-hint\">英字フォントはラテン文字にのみ適用され、漢字は上の中国語フォントのままです。紙面上の文字をダブルタップすると直接入力できます。パネルを閉じた後、420ms 長押ししてロックを解除すると、四隅をドラッグして枠を変更したり、右側のハンドルをドラッグして回転したりできます。</div>",
  "fr": "<div class=\"diy-hint\">La police anglaise ne s'applique qu'aux lettres latines ; les caractères chinois utilisent toujours la police chinoise ci-dessus. Double-tapez le texte sur le papier pour saisir directement. Après avoir fermé le panneau, appuyez longuement 420 ms pour déverrouiller, puis faites glisser les quatre coins pour redimensionner le cadre ou la poignée droite pour faire pivoter.</div>",
  "es": "<div class=\"diy-hint\">La fuente inglesa solo afecta a las letras latinas; los caracteres chinos siguen usando la fuente china de arriba. Haz doble clic en el texto del papel para escribir directamente. Tras cerrar el panel, mantén pulsado 420 ms para desbloquear y poder arrastrar las cuatro esquinas para cambiar el marco o el tirador derecho para girar.</div>"
 },
 "<div class=\"diy-hint\">选「透明」时封面彩带隐藏，左侧也不画书槽。</div>": {
  "zhCN": "<div class=\"diy-hint\">选「透明」时封面彩带隐藏，左侧也不画书槽。</div>",
  "zhTW": "<div class=\"diy-hint\">選「透明」時封面彩帶隱藏，左側也不畫書槽。</div>",
  "en": "<div class=\"diy-hint\">When \"Transparent\" is selected, the cover ribbon is hidden and no spine groove is drawn on the left either.</div>",
  "ja": "<div class=\"diy-hint\">「透明」を選ぶと表紙のリボンが非表示になり、左側に背の溝も描かれません。</div>",
  "fr": "<div class=\"diy-hint\">Lorsque « Transparent » est sélectionné, le ruban de la couverture est masqué et aucune rainure n'est tracée à gauche non plus.</div>",
  "es": "<div class=\"diy-hint\">Al seleccionar \"Transparente\", la cinta de la portada se oculta y tampoco se dibuja la ranura del lomo a la izquierda.</div>"
 },
