  "zhCN": "答案区分大小写，首尾空格会自动忽略；答案先取 MD5 再解密内容。",
  "zhTW": "答案區分大小寫，首尾空格會自動忽略；答案先取 MD5 再解密內容。",
  "en": "Answers are case-sensitive; leading and trailing spaces are ignored automatically. The answer is hashed with MD5 before decrypting the content.",
  "ja": "答えは大文字と小文字を区別し、前後の空白は自動的に無視されます。答えは MD5 でハッシュしてから内容を復号します。",
  "fr": "Les réponses sont sensibles à la casse ; les espaces au début et à la fin sont ignorés automatiquement. La réponse est hachée en MD5 avant de déchiffrer le contenu.",
